text:
.ui-test-framework {
  --ui-test-bg: #10151c;
  --ui-test-fg: #e6edf3;
  --ui-test-muted: #8b98a7;
  --ui-test-border: #475569;
  --ui-test-accent: #64d8e8;
  position: fixed;
  z-index: 1000;
  bottom: max(18px, env(safe-area-inset-bottom));
  left: max(18px, env(safe-area-inset-left));
  color: var(--ui-test-fg);
  font: 12px/1.35 ui-monospace, "SFMono-Regular", Menlo, Monaco, Consolas, monospace;
}

.ui-test-framework *, .ui-test-framework *::before, .ui-test-framework *::after { box-sizing: border-box; }

.ui-test-framework__dial {
  display: grid;
  width: 50px;
  height: 50px;
  border: 1px solid color-mix(in srgb, var(--ui-test-accent) 75%, white);
  border-radius: 50%;
  place-items: center;
  background: radial-gradient(circle at 35% 30%, #263747, var(--ui-test-bg) 68%);
  box-shadow: 0 8px 30px rgb(0 0 0 / 48%), inset 0 0 0 3px rgb(100 216 232 / 8%);
  color: var(--ui-test-accent);
  font: 800 11px/1 ui-monospace, monospace;
  letter-spacing: 0.08em;
  cursor: pointer;
}

.ui-test-framework__dial:hover,
.ui-test-framework__dial:focus-visible {
  outline: 2px solid var(--ui-test-accent);
  outline-offset: 3px;
  color: white;
  transform: translateY(-1px);
}

.ui-test-framework__panel {
  position: absolute;
  bottom: 62px;
  left: 0;
  width: min(320px, calc(100vw - 36px));
  max-height: min(560px, calc(100dvh - 100px));
  overflow: auto;
  border: 1px solid var(--ui-test-border);
  border-radius: 8px;
  background: color-mix(in srgb, var(--ui-test-bg) 96%, transparent);
  box-shadow: 0 18px 55px rgb(0 0 0 / 58%);
  backdrop-filter: blur(12px);
}

.ui-test-framework__panel > header {
  position: sticky;
  z-index: 1;
  top: 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  border-bottom: 1px solid rgb(148 163 184 / 18%);
  padding: 11px 12px;
  background: var(--ui-test-bg);
}

.ui-test-framework__panel > header div { display: grid; gap: 2px; }
.ui-test-framework__panel > header span { color: var(--ui-test-accent); font-size: 8px; letter-spacing: 0.16em; }
.ui-test-framework__panel > header strong { font-size: 12px; }
.ui-test-framework__panel > header button { border: 0; background: transparent; color: var(--ui-test-muted); font: inherit; cursor: pointer; }
.ui-test-framework__panel > header button:hover:not(:disabled) { color: var(--ui-test-accent); }
.ui-test-framework__panel > header button:disabled { opacity: 0.35; }
.ui-test-framework__controls { display: grid; gap: 1px; background: rgb(148 163 184 / 12%); }

.ui-test-framework__control {
  position: relative;
  display: grid;
  min-width: 0;
  gap: 7px;
  padding: 11px 12px;
  background: var(--ui-test-bg);
}

.ui-test-framework__control > label { display: flex; min-width: 0; align-items: center; justify-content: space-between; gap: 8px; }
.ui-test-framework__control > label span { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.ui-test-framework__control output { color: var(--ui-test-accent); font-size: 10px; }
.ui-test-framework__control small { color: var(--ui-test-muted); font-size: 9px; }
.ui-test-framework__control select { width: 100%; }
.ui-test-framework__control select,
.ui-test-framework__control input[type="color"] {
  min-height: 32px;
  border: 1px solid var(--ui-test-border);
  border-radius: 4px;
  padding: 4px 7px;
  background: #0a0f15;
  color: inherit;
  font: inherit;
}
.ui-test-framework__control input[type="range"] { width: 100%; accent-color: var(--ui-test-accent); }
.ui-test-framework__control input[type="checkbox"] { position: absolute; top: 10px; right: 12px; width: 30px; height: 18px; accent-color: var(--ui-test-accent); }
.ui-test-framework__control:has(input[type="checkbox"]) > label { padding-right: 38px; }
.ui-test-framework__control input:focus-visible,
.ui-test-framework__control select:focus-visible { outline: 2px solid var(--ui-test-accent); outline-offset: 2px; }

@media (max-width: 520px) {
  .ui-test-framework { bottom: 12px; left: 12px; }
  .ui-test-framework__panel { width: calc(100vw - 24px); }
}
